import React from 'react';
import {
  Card,
  CardMedia,
  CardContent,
  CardActions,
  Typography,
  Button,
  IconButton,
} from '@mui/material';
import { ShoppingCart, Favorite } from '@mui/icons-material';
import { useDispatch } from 'react-redux';
import { addToCart } from '../features/cartSlice';
import { motion } from 'framer-motion';

const ProductCard = ({ product }) => {
  const dispatch = useDispatch();

  const handleAddToCart = () => {
    dispatch(addToCart(product));
  };

  return (
    <motion.div
      whileHover={{ scale: 1.05, boxShadow: '0 4px 16px rgba(0,0,0,0.12)' }}
      style={{
        border: '1px solid #eee',
        borderRadius: 8,
        padding: 16,
        textAlign: 'center',
        background: '#fff'
      }}
    >
      <img
        src={product.image}
        alt={product.name}
        style={{ width: '100%', height: 120, objectFit: 'cover', marginBottom: 12, borderRadius: 4 }}
      />
      <h3 style={{ margin: '12px 0 8px' }}>{product.name}</h3>
      <p style={{ margin: '8px 0' }}>${product.price}</p>
      <button
        onClick={handleAddToCart}
        style={{
          padding: '8px 16px',
          background: '#61dafb',
          color: '#fff',
          border: 'none',
          borderRadius: 4,
          cursor: 'pointer'
        }}
      >
        Add to Cart
      </button>
    </motion.div>
  );
};

export default ProductCard;
